source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    blocks = []
    # Find monochrome, nonzero 3x3 solid blocks.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                if not any((r, c) == (br, bc) for br, bc, _ in blocks):
                    blocks.append((r, c, color))
    out = [row[:] for row in grid]
    centers = [(r + 1, c + 1, color) for r, c, color in blocks]
    # Project each block's center row and column across the grid.
    for cr, cc, color in centers:
        for x in range(w):
            out[cr][x] = color
        for y in range(h):
            out[y][cc] = color
    # Where a row projection meets a column projection from another block,
    # leave the crossing empty. The blocks themselves remain unchanged.
    block_cells = {(r + dr, c + dc) for r, c, _ in blocks
                   for dr in range(3) for dc in range(3)}
    for hr, hc, hcolor in centers:
        for vr, vc, vcolor in centers:
            if (hr, vc) not in block_cells and hr != vr:
                out[hr][vc] = 0
            if (vr, hc) not in block_cells and vr != hr:
                out[vr][hc] = 0
    return out
'''
